SELECT DISTINCT CAST(shelve_id AS CHAR) FROM cage_shelf_index WHERE deleted = 0
AND CAST(room_id AS CHAR) IN #{rid}
AND 1 = 0

SELECT * FROM cage_shelf_index
ORDER BY campus_id, area_id, floor_id, room_id, shelve_id
LIMIT #{limit}
